using System.Reflection;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

Console.WriteLine("=== Microsoft.Agents.AI - Key Types ===\n");
PrintTypes(typeof(ChatClientAgent).Assembly);

Console.WriteLine("\n=== Microsoft.Extensions.AI - Key Types ===\n");
PrintTypes(typeof(IChatClient).Assembly);

Console.WriteLine("\n=== Detailed Info ===\n");
PrintTypeDetails("ChatClientAgent", typeof(ChatClientAgent).Assembly);
PrintTypeDetails("ChatClientAgentOptions", typeof(ChatClientAgentOptions).Assembly);
PrintTypeDetails("IChatClient", typeof(IChatClient).Assembly);

void PrintTypes(Assembly asm)
{
    var types = asm.GetTypes()
        .Where(t => t.IsPublic && !t.Name.StartsWith("<") && t.Namespace?.StartsWith("Microsoft") == true)
        .OrderBy(t => t.Name)
        .ToList();

    foreach (var type in types.Take(50))
    {
        var kind = type.IsInterface ? "interface" : type.IsAbstract ? "abstract" : "class";
        Console.WriteLine($"• {type.Name} ({kind})");
    }
    if (types.Count > 50)
        Console.WriteLine($"... and {types.Count - 50} more types");
}

void PrintTypeDetails(string typeName, Assembly asm)
{
    var type = asm.GetTypes().FirstOrDefault(t => t.Name == typeName);
    if (type == null) return;

    Console.WriteLine($"\n--- {typeName} ---");
    Console.WriteLine($"Namespace: {type.Namespace}");
    Console.WriteLine($"Kind: {(type.IsInterface ? "Interface" : type.IsAbstract ? "Abstract Class" : "Class")}");

    Console.WriteLine("\nPublic Methods:");
    var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
        .Where(m => !m.IsSpecialName)
        .Take(20);
    foreach (var method in methods)
    {
        var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  - {method.Name}({parms})");
    }

    Console.WriteLine("\nPublic Properties:");
    var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Take(20);
    foreach (var prop in props)
    {
        Console.WriteLine($"  - {prop.Name}: {prop.PropertyType.Name}");
    }
}
