using System.Reflection;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI.Chat;

Console.WriteLine("=== MICROSOFT.AGENTS.AI - CORE AGENT TYPES ===\n");

// ChatClientAgent
PrintTypeInfo(typeof(ChatClientAgent));

// ChatClientAgentOptions  
PrintTypeInfo(typeof(ChatClientAgentOptions));

// ChatClientAgentRunOptions
PrintTypeInfo(typeof(ChatClientAgentRunOptions));

Console.WriteLine("\n=== MICROSOFT.EXTENSIONS.AI - TOOL/FUNCTION TYPES ===\n");

// IChatClient
PrintTypeInfo(typeof(IChatClient));

// AIFunction  
PrintTypeInfo(typeof(AIFunction));

// AIFunctionFactory
PrintTypeInfo(typeof(AIFunctionFactory));

// AIFunctionDeclaration
PrintTypeInfo(typeof(AIFunctionDeclaration));

// AITool
PrintTypeInfo(typeof(AITool));

Console.WriteLine("\n=== MICROSOFT.EXTENSIONS.AI.OPENAI - OPENAI CLIENT ===\n");

// Check for OpenAIChatClient
var openaiAsm = typeof(Microsoft.Extensions.AI.OpenAIClientExtensions).Assembly;
var openaiChatClient = openaiAsm.GetTypes().FirstOrDefault(t => t.Name == "OpenAIChatClient");
if (openaiChatClient != null)
    PrintTypeInfo(openaiChatClient);

void PrintTypeInfo(Type type)
{
    Console.WriteLine($"=== {type.Name} ===");
    if (type.IsInterface)
        Console.WriteLine($"Kind: Interface");
    else if (type.IsAbstract)
        Console.WriteLine($"Kind: Abstract Class");
    else
        Console.WriteLine($"Kind: Class");

    Console.WriteLine($"Namespace: {type.Namespace}");

    if (type.BaseType != null && type.BaseType != typeof(object))
        Console.WriteLine($"Base: {type.BaseType.Name}");

    var interfaces = type.GetInterfaces();
    if (interfaces.Length > 0)
    {
        Console.WriteLine($"Implements: {string.Join(", ", interfaces.Select(i => i.Name).Take(3))}");
    }

    Console.WriteLine("\nConstructors:");
    var ctors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
    if (ctors.Length == 0)
        Console.WriteLine("  (none)");
    foreach (var ctor in ctors.Take(5))
    {
        var parms = string.Join(", ", ctor.GetParameters().Select(p => p.ParameterType.Name));
        Console.WriteLine($"  + .ctor({parms})");
    }

    Console.WriteLine("\nPublic Methods:");
    var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
        .Where(m => !m.IsSpecialName)
        .OrderBy(m => m.Name)
        .Take(15);

    if (!methods.Any())
        Console.WriteLine("  (none)");

    foreach (var method in methods)
    {
        var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name}"));
        var ret = method.ReturnType.Name;
        var isAsync = method.ReturnType.Name.StartsWith("Task");
        var asyncMarker = isAsync ? " [async]" : "";
        Console.WriteLine($"  + {method.Name}({parms}): {ret}{asyncMarker}");
    }

    Console.WriteLine("\nPublic Properties:");
    var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
        .OrderBy(p => p.Name)
        .Take(10);

    if (!props.Any())
        Console.WriteLine("  (none)");

    foreach (var prop in props)
    {
        var canGet = prop.CanRead ? "get" : "";
        var canSet = prop.CanWrite ? "set" : "";
        var accessors = string.Join("/", new[] { canGet, canSet }.Where(x => !string.IsNullOrEmpty(x)));
        Console.WriteLine($"  + {prop.Name}: {prop.PropertyType.Name} [{accessors}]");
    }

    Console.WriteLine();
}
