            var isAsync = method.ReturnType.Name.StartsWith("Task") ? "[async]" : "";
            Console.WriteLine($"    • {method.Name}({parms}): {method.ReturnType.Name} {isAsync}");
        }
    }

    Console.WriteLine();
}
