+using System.ComponentModel;
+using System.Text.Json;
+using Microsoft.Extensions.Logging;
+
+namespace ResearchAgent.Tools;
+
+/// <summary>
+/// Provides web search capability using the Brave Search API.
+/// Falls back to simulated results when no API key is configured.
+/// </summary>
+public sealed class WebSearchTool(IHttpClientFactory httpClientFactory, ILogger<WebSearchTool> logger)
+{
+    [Description("Searches the web for information on a given query and returns relevant results. " +
+                 "Use this tool to find current information, facts, and data about any topic.")]
+    public async Task<string> SearchWebAsync(
+        [Description("The search query to look up on the web")] string query,
+        [Description("Maximum number of results to return (1-10)")] int maxResults = 5,
+        CancellationToken cancellationToken = default)
+    {
+        logger.LogInformation("Searching web for: {Query}", query);
+
+        maxResults = Math.Clamp(maxResults, 1, 10);
+
+        var apiKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
+        if (!string.IsNullOrWhiteSpace(apiKey))
+        {
+            return await SearchWithBraveAsync(query, maxResults, apiKey, cancellationToken);
+        }
+
+        logger.LogWarning("BRAVE_SEARCH_API_KEY not set — returning simulated results");
+        return GetSimulatedResults(query);
+    }
+
+    private async Task<string> SearchWithBraveAsync(
+        string query, int maxResults, string apiKey, CancellationToken ct)
+    {
+        var client = httpClientFactory.CreateClient("BraveSearch");
+        client.DefaultRequestHeaders.Add("X-Subscription-Token", apiKey);
+        client.DefaultRequestHeaders.Add("Accept", "application/json");
+
+        var url = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}";
+
+        var response = await client.GetAsync(url, ct);
+        response.EnsureSuccessStatusCode();
+
+        using var doc = await JsonDocument.ParseAsync(
+            await response.Content.ReadAsStreamAsync(ct), cancellationToken: ct);
+
+        var results = new List<string>();
+        if (doc.RootElement.TryGetProperty("web", out var web) &&
+            web.TryGetProperty("results", out var items))
+        {
+            foreach (var item in items.EnumerateArray())
+            {
+                var title = item.GetProperty("title").GetString();
+                var description = item.GetProperty("description").GetString();
+                var itemUrl = item.GetProperty("url").GetString();
+                results.Add($"**{title}**\n{description}\nSource: {itemUrl}");
+            }
+        }
+
+        return results.Count > 0
+            ? string.Join("\n\n---\n\n", results)
+            : "No results found.";
+    }
+
+    private static string GetSimulatedResults(string query) =>
+        $"""
+        [Simulated search results for "{query}"]
+
+        1. **Overview of {query} — Wikipedia**
+           A comprehensive overview covering the history, key concepts, and recent developments
+           related to {query}. This topic has seen significant interest from researchers worldwide.
+           Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
+
+        2. **Recent Advances in {query} — Nature**
+           A 2025 review article discussing breakthroughs and emerging trends in {query},
+           highlighting practical applications and future directions.
+           Source: https://nature.com/articles/recent-advances-{Uri.EscapeDataString(query)}
+
+        3. **{query}: A Practical Guide — TechReview**
+           An in-depth practical guide exploring real-world uses of {query}, common challenges,
+           and best practices drawn from industry experience.
+           Source: https://techreview.com/guide/{Uri.EscapeDataString(query)}
+
+        Note: These are simulated results. Set the BRAVE_SEARCH_API_KEY environment variable
+        to get real search results from the Brave Search API.
+        """;
+}
